"""VisualComparator — golden-screenshot regression.

@concept CONCEPT-taf-v1-004-01-the-artifacts

The artifact grammar: goldens/<name>_Expected.png is the approved
baseline; a run writes <test>/<name>_Actual.png beside the journal and
<name>_Diff.html (Expected | Actual side by side) on mismatch. A
missing baseline fails the test — `taf promote` approves Actual as the
new Expected.
"""

import glob
import os
import shutil

from taf_runtime import journal as taf_journal

ROWS = []  # (name, status, expected, actual) — write_report renders them


def goldens_dir():
    """TAF_GOLDENS or <suite>/goldens — the suite dir is where its
    sut_config lives."""
    if os.environ.get("TAF_GOLDENS"):
        return os.environ["TAF_GOLDENS"]
    try:
        import sut_config
        return os.path.join(os.path.dirname(sut_config.__file__), "goldens")
    except ImportError:
        return "goldens"


def _bytes(path):
    with open(path, "rb") as f:
        return f.read()


def _diff_html(name, expected, actual):
    return ("<!doctype html><meta charset=utf-8><title>diff %s</title>"
            "<h2>%s</h2><table><tr><th>Expected</th><th>Actual</th></tr>"
            "<tr><td><img src=\"file://%s\" style=max-width:48vw></td>"
            "<td><img src=\"file://%s\" style=max-width:48vw></td></tr>"
            "</table>" % (name, name, expected, actual))


def compare(page, name, mask=None):
    """Screenshot → <test>/<name>_Actual.png; assert it equals the
    <name>_Expected.png baseline. mask: locators excluded from the shot."""
    d = taf_journal.test_dir()
    actual = os.path.join(d, name + "_Actual.png")
    opts = {"path": actual}
    if mask:
        opts["mask"] = list(mask)
    page.screenshot(**opts)
    expected = os.path.join(goldens_dir(), name + "_Expected.png")
    if not os.path.exists(expected):
        ROWS.append((name, "no-baseline", expected, actual))
        taf_journal.event("visual", name=name, outcome="no-baseline")
        raise AssertionError(
            "no baseline for %r — inspect %s then `taf promote` approves it"
            % (name, actual))
    if _bytes(actual) == _bytes(expected):
        ROWS.append((name, "ok", expected, actual))
        taf_journal.event("visual", name=name, outcome="ok")
        return
    diff = os.path.join(d, name + "_Diff.html")
    with open(diff, "w", encoding="utf-8") as f:
        f.write(_diff_html(name, expected, actual))
    ROWS.append((name, "diff", expected, actual))
    taf_journal.event("visual", name=name, outcome="diff")
    raise AssertionError(
        "screenshot %r differs from the baseline — see %s; "
        "`taf promote` approves the new image" % (name, diff))


def write_report(run_dir):
    """The run's side-by-side report — visual-report.html in the run dir."""
    if not ROWS:
        return None
    rows = "".join(
        "<tr><td>%s</td><td>%s</td><td><a href=\"file://%s\">expected</a></td>"
        "<td><a href=\"file://%s\">actual</a></td></tr>"
        % (n, s, e or "", a or "") for n, s, e, a in ROWS)
    path = os.path.join(run_dir, "visual-report.html")
    with open(path, "w", encoding="utf-8") as f:
        f.write("<!doctype html><meta charset=utf-8><title>visual report</title>"
                "<h2>visual comparisons</h2><table border=1>"
                "<tr><th>name</th><th>status</th><th>expected</th><th>actual</th></tr>"
                + rows + "</table>")
    return path


def promote(results_dir, goldens):
    """Approve Actual images as the new Expected baselines — the human
    has looked; the copy is the approval."""
    moved = []
    os.makedirs(goldens, exist_ok=True)
    for actual in sorted(glob.glob(
            os.path.join(results_dir, "**", "*_Actual.png"), recursive=True)):
        name = os.path.basename(actual)[:-len("_Actual.png")]
        dst = os.path.join(goldens, name + "_Expected.png")
        shutil.copyfile(actual, dst)
        moved.append(dst)
    return moved
